"""Español — virtudes (virtues_001 … virtues_050)."""

T = {
"virtues_001": ("Según un hadiz narrado por el imam al-Bujari, ¿qué debe hacer con sus palabras quien cree en Allah y en el Último Día?", ["Decir el bien o callar", "Hablar alto", "No hablar nunca", "Repetir rumores"], "El Profeta ﷺ dijo: «Quien crea en Allah y en el Último Día, que diga el bien o que calle»."),
"virtues_002": ("Según ese mismo hadiz, ¿a quién más debe honrar el creyente, además de a su huésped?", ["A su vecino", "A su comerciante", "A su rival", "A un desconocido"], "El hadiz continúa: «…y quien crea en Allah y en el Último Día, que honre a su vecino»."),
"virtues_003": ("Ese mismo hadiz también menciona honrar a quién, cuando llega a casa de uno.", ["Al huésped", "Solo al vecino", "Al comerciante", "A un viajero desconocido y lejano"], "El hadiz completo dice: «…quien crea en Allah y en el Último Día, que honre a su huésped»."),
"virtues_004": ("Según un hadiz auténtico, la fe de un creyente no es completa hasta que ama para su hermano lo que ama para…", ["sí mismo", "su riqueza", "solo su familia", "su país"], "El Profeta ﷺ dijo: «Ninguno de vosotros cree de verdad hasta que ama para su hermano lo que ama para sí mismo»."),
"virtues_005": ("Según un hadiz auténtico, el verdadero musulmán es aquel de cuya lengua y ___ están a salvo los demás.", ["mano", "riqueza", "mirada", "voz"], "El Profeta ﷺ dijo: «El musulmán es aquel de cuya lengua y mano están a salvo los demás musulmanes»."),
"virtues_006": ("El Corán ordena la bondad con los padres y prohíbe decirles incluso qué palabra de fastidio.", ["«Uf» (un sonido de impaciencia)", "«No»", "«Basta»", "«Espera»"], "El Corán exige la máxima bondad con los padres, prohibiendo hasta la más leve palabra de desprecio."),
"virtues_007": ("¿Con qué compara el Corán la maledicencia (hablar mal de un ausente)?", ["Con comer la carne del propio hermano muerto", "Con beber agua salada", "Con caminar en la oscuridad", "Con sembrar en la arena"], "«¿Le gustaría a alguno de vosotros comer la carne de su hermano muerto? ¡Lo detestaríais!»: así de fea es la maledicencia."),
"virtues_008": ("¿Cómo describe el Corán la relación entre los creyentes?", ["Son hermanos", "Son competidores", "Son extraños", "Son socios comerciales"], "«Los creyentes no son sino hermanos; reconciliad, pues, a vuestros dos hermanos.»"),
"virtues_009": ("¿Qué dice el Corán sobre burlarse de los demás?", ["Está prohibido: los burlados pueden ser mejores que los burladores", "Está permitido entre amigos", "Está permitido si es gracioso", "Está reservado a los poetas"], "«Que unos no se burlen de otros: quizá sean mejores que ellos.»"),
"virtues_010": ("Según el Corán, ¿qué promete Allah a quien es agradecido?", ["Que le dará más", "Una larga vida", "Riqueza inmediata", "Un viaje"], "«Si sois agradecidos, os daré más.»"),
"virtues_011": ("Según el Corán, ¿cómo recibirán su recompensa los pacientes (sabirun)?", ["Completa, sin medida", "Toda de una vez", "Tras cuarenta días", "Según su riqueza"], "«Los pacientes recibirán su recompensa completa, sin cuenta.»"),
"virtues_012": ("«Comed y bebed, pero…»: ¿cómo continúa este versículo?", ["No derrochéis", "No compartáis", "No habléis", "No salgáis"], "«Comed y bebed, pero no os excedáis: Allah no ama a los derrochadores.»"),
"virtues_013": ("¿Qué versículo, recitado a menudo en el sermón del viernes, resume lo que Allah ordena?", ["«Allah ordena la justicia y el bien»", "«Allah ordena el comercio»", "«Allah ordena viajar»", "«Allah ordena el silencio»"], "«Allah ordena la justicia, el bien y la generosidad con los parientes…»: se recita cada viernes."),
"virtues_014": ("¿Contra quiénes comienza la sura Al-Mutaffifin con «¡Ay de…»?", ["Los que defraudan en la medida y el peso", "Los que duermen", "Los que viajan", "Los que callan"], "«¡Ay de los defraudadores: que exigen la medida completa al recibir, pero dan de menos al medir para otros!»"),
"virtues_015": ("Según la sura Ad-Duha, ¿cómo hay que tratar al huérfano y al que pide?", ["Ni oprimirlos ni rechazarlos", "Ignorarlos", "Enviarlos a otros", "Hablarles más tarde"], "«Al huérfano, no lo oprimas; y al que pide, no lo rechaces.»"),
"virtues_016": ("¿Cómo ordena el Corán hablar a la gente?", ["Con buenas palabras", "En voz muy baja", "Lo menos posible", "Solo a los parientes"], "«…y hablad a la gente con bondad»: la palabra amable es en sí misma adoración."),
"virtues_017": ("En sus consejos a su hijo, ¿qué dice Luqman sobre el andar y el orgullo?", ["No andes por la tierra con arrogancia", "Anda siempre deprisa", "Anda solo de noche", "No andes nunca solo"], "«No apartes tu rostro de la gente con orgullo, ni andes por la tierra con arrogancia.»"),
"virtues_018": ("Según el primerísimo hadiz de la colección de al-Bujari, ¿de qué dependen las obras?", ["De las intenciones", "De los resultados", "De las costumbres", "De los testigos"], "«Las obras dependen de las intenciones, y cada persona tendrá lo que haya pretendido.»"),
"virtues_019": ("Según un hadiz de al-Bujari, ¿adónde conduce la veracidad (sidq)?", ["A la rectitud, y la rectitud conduce al Paraíso", "A la riqueza", "A la fama", "A la fuerza"], "«La veracidad conduce a la rectitud, y la rectitud conduce al Paraíso; la mentira conduce a la perversidad, y la perversidad al Fuego.»"),
"virtues_020": ("Según un hadiz auténtico, ¿cuáles son las tres señales del hipócrita?", ["Miente al hablar, rompe su promesa y traiciona la confianza", "Duerme, come y habla demasiado", "Viaja, comercia y canta", "Reza poco, ayuna poco y lee poco"], "«Las señales del hipócrita son tres: cuando habla miente, cuando promete no cumple, y cuando se le confía algo traiciona.»"),
"virtues_021": ("Un hombre pidió consejo al Profeta ﷺ; ¿qué le repitió varias veces?", ["«No te enfades»", "«Viaja mucho»", "«Come poco»", "«Habla alto»"], "El hombre dijo: «Aconséjame». Respondió: «No te enfades». El hombre insistió, y repitió: «No te enfades»."),
"virtues_022": ("Según el Profeta ﷺ, ¿quién es verdaderamente fuerte?", ["Quien se domina en la ira", "Quien gana en la lucha", "Quien carga los pesos más grandes", "Quien corre más rápido"], "«El fuerte no es el que vence a los demás luchando; el fuerte es el que se domina en el momento de la ira.»"),
"virtues_023": ("Según un hadiz de al-Bujari, ¿de qué forma parte el pudor (haya')?", ["De la fe", "De la debilidad", "De la riqueza", "De la timidez reprobable"], "Al ver a un hombre reprochar a su hermano su pudor, el Profeta ﷺ dijo: «Déjalo, pues el pudor forma parte de la fe»."),
"virtues_024": ("¿Qué dijo el Profeta ﷺ a un hombre que se jactaba de no haber besado nunca a ninguno de sus diez hijos?", ["«Quien no tiene misericordia no recibirá misericordia»", "«Tienes razón»", "«Los niños no importan»", "«Es un asunto privado»"], "El Profeta ﷺ besaba a sus nietos; a Al-Aqra', que se sorprendió, le respondió: «Man la yarham la yurham»."),
"virtues_025": ("Según un hadiz de al-Bujari, ¿por qué acto fue perdonado un hombre?", ["Por dar de beber a un perro sediento", "Por construir un pozo", "Por plantar un árbol", "Por ahuyentar a un lobo"], "El hombre bajó a un pozo, llenó su zapato de agua y dio de beber al perro que jadeaba de sed; Allah lo perdonó."),
"virtues_026": ("Según un hadiz auténtico, ¿por qué fue castigada una mujer?", ["Por encerrar a un gato sin alimentarlo ni dejarlo buscar comida", "Por vender un gato", "Por echar a un gato de su casa", "Por adoptar demasiados gatos"], "«Una mujer fue castigada por un gato que encerró hasta que murió: ni lo alimentó ni lo dejó comer de las criaturas de la tierra.»"),
"virtues_027": ("¿De quién dijo el Profeta ﷺ que Yibril le hizo tantas recomendaciones que pensó que lo haría heredero?", ["Del vecino", "Del huésped", "Del huérfano", "Del viajero"], "«Yibril no dejó de recomendarme al vecino, hasta el punto de que pensé que lo haría heredar.»"),
"virtues_028": ("Según un hadiz de al-Bujari, ¿cuántos derechos tiene el musulmán sobre su hermano musulmán?", ["Cinco", "Tres", "Siete", "Diez"], "«Devolver el saludo, visitar al enfermo, acompañar el funeral, aceptar la invitación y responder al que estornuda.»"),
"virtues_029": ("A la pregunta «¿Qué islam es el mejor?», ¿qué respondió el Profeta ﷺ?", ["Dar de comer y saludar a quien conoces y a quien no conoces", "Construir mezquitas", "Viajar mucho", "Hablar poco"], "«Dar de comer, y dirigir el saludo a quien conoces y a quien no conoces.»"),
"virtues_030": ("¿Con qué compara el Profeta ﷺ a los creyentes en su afecto y ayuda mutua?", ["Con un solo cuerpo: si un miembro sufre, todo el cuerpo vela con fiebre", "Con un bosque", "Con una caravana", "Con un rebaño"], "«Los creyentes, en su amor, misericordia y compasión mutuos, son como un solo cuerpo.»"),
"virtues_031": ("Según el Profeta ﷺ, ¿qué es «la más mentirosa de las palabras»?", ["La sospecha (zann)", "La poesía", "La broma", "El silencio"], "«Guardaos de la sospecha, pues la sospecha es la más mentirosa de las palabras.»"),
"virtues_032": ("Según un hadiz auténtico, ¿cuántos días como máximo puede un musulmán dejar de hablar a su hermano?", ["Tres días", "Siete días", "Un mes", "Un año"], "«No es lícito a un hombre dejar de hablar a su hermano más de tres noches… y el mejor de los dos es el que saluda primero.»"),
"virtues_033": ("Según el Profeta ﷺ, ¿cuál es el valor de cada buena acción, por pequeña que sea?", ["Es una limosna (sadaqa)", "No cuenta", "Vale un dinar", "Sustituye a la oración"], "«Toda buena acción es una limosna.»"),
"virtues_034": ("Según un hadiz de Sahih Muslim, ¿cuál es la rama más humilde de la fe?", ["Retirar del camino lo que daña", "Construir una mezquita", "Recitar un yuz'", "Ayunar un día"], "«La fe tiene setenta y tantas ramas: la más alta es “la ilaha illa Allah”, la más humilde es retirar del camino lo que daña; y el pudor es una rama de la fe.»"),
"virtues_035": ("Según un hadiz de Sahih Muslim, la limpieza (tahara) es…", ["La mitad de la fe", "Un tercio de la fe", "Un décimo de la fe", "Ajena a la fe"], "«La pureza es la mitad de la fe, y “al-hamdu li-Llah” llena la balanza.»"),
"virtues_036": ("El Profeta ﷺ dijo: «La religión es nasiha (consejo sincero)». ¿Hacia quién?", ["Hacia Allah, Su Libro, Su Mensajero, los dirigentes y todos los musulmanes", "Solo hacia uno mismo", "Hacia los ricos", "Hacia los extraños"], "Preguntaron: «¿Hacia quién?». Dijo: «Hacia Allah, Su Libro, Su Mensajero, los dirigentes de los musulmanes y su gente común»."),
"virtues_037": ("Según un hadiz de Sahih Muslim, ¿qué mira Allah en Sus siervos?", ["Sus corazones y sus obras", "Su apariencia", "Su riqueza", "Su número"], "«Allah no mira vuestros cuerpos ni vuestra apariencia, sino que mira vuestros corazones y vuestras obras.»"),
"virtues_038": ("Según un hadiz de Sahih Muslim, ¿qué hace Allah por quien alivia a un creyente de una dificultad de este mundo?", ["Lo alivia de una dificultad del Día de la Resurrección", "Lo hace rico", "Le concede larga vida", "Lo hace famoso"], "«Quien alivie a un creyente de una pena de este mundo, Allah lo aliviará de una pena del Día de la Resurrección.»"),
"virtues_039": ("Según el Profeta ﷺ, ¿qué hace Allah por quien recorre un camino en busca de conocimiento?", ["Le facilita un camino hacia el Paraíso", "Lo dispensa de rezar", "Lo hace rico", "Lo hace rey"], "«A quien recorra un camino en busca de conocimiento, Allah le facilitará con ello un camino hacia el Paraíso.»"),
"virtues_040": ("Según un hadiz de al-Bujari, ¿quién es «el mejor de vosotros»?", ["Quien aprende el Corán y lo enseña", "Quien mejor habla", "Quien más posee", "Quien más viaja"], "«El mejor de vosotros es quien aprende el Corán y lo enseña.»"),
"virtues_041": ("¿Cómo definió el Profeta ﷺ la arrogancia (kibr)?", ["Rechazar la verdad y despreciar a la gente", "Llevar ropa bonita", "Gustar de buenos zapatos", "Andar deprisa"], "Al hombre que amaba la ropa bonita le dijo: «Allah es bello y ama la belleza. La arrogancia es rechazar la verdad y despreciar a la gente»."),
"virtues_042": ("Según un hadiz de al-Bujari, ¿cuáles son las dos bendiciones que mucha gente desaprovecha?", ["La salud y el tiempo libre", "El dinero y la fama", "La fuerza y la belleza", "La familia y los amigos"], "«Hay dos bendiciones en las que mucha gente sale perdiendo: la salud y el tiempo libre.»"),
"virtues_043": ("Completa este hadiz: «El creyente no es picado dos veces…»", ["«…desde el mismo agujero»", "«…por el mismo escorpión»", "«…en el mismo día»", "«…por la misma abeja»"], "«La yuldagu al-mu'minu min yuhrin wahidin marratayn»: el creyente aprende de sus errores."),
"virtues_044": ("¿Con qué compara el Profeta ﷺ al buen compañero, frente al herrero?", ["Con el vendedor de almizcle", "Con el panadero", "Con el pastor", "Con el vendedor de telas"], "«El buen compañero es como el portador de almizcle: te da un poco, o le compras, o hueles su fragancia; el malo es como el fuelle del herrero.»"),
"virtues_045": ("Según un hadiz de al-Bujari, ¿de qué es responsable cada uno de nosotros, «como un pastor»?", ["De quienes están a su cargo", "Del tiempo", "De las estrellas", "De las cosechas de otros"], "«Cada uno de vosotros es un pastor, y cada uno es responsable de su rebaño»: el gobernante de su pueblo, el hombre de su familia, la mujer de su casa."),
"virtues_046": ("Según el Corán, ¿qué ocurre si se repele el mal con lo que es mejor?", ["Quien era enemigo se vuelve como un amigo cercano", "El mal desaparece de la tierra", "Uno se hace rico", "Nada cambia"], "«Repele el mal con lo que es mejor, y aquel con quien tenías enemistad será como un amigo cercano» (41:34)."),
"virtues_047": ("¿Cómo responden «los siervos del Misericordioso» a los ignorantes que los provocan, según la sura Al-Furqan?", ["Dicen: «¡Paz!»", "Responden con ira", "Se burlan de ellos", "Los golpean"], "«Los siervos del Misericordioso andan por la tierra con humildad, y cuando los ignorantes les hablan, dicen: ¡Paz!» (25:63)."),
"virtues_048": ("¿Qué dice el Corán sobre el compromiso (la promesa, el pacto)?", ["«Cumplid el compromiso, pues del compromiso se pedirán cuentas»", "«Una promesa no obliga a nadie»", "«Prometed solo a los ricos»", "«No prometáis nunca»"], "«Y cumplid el compromiso, pues del compromiso se pedirán cuentas» (17:34)."),
"virtues_049": ("¿De quiénes dice el Corán que son «los hermanos de los demonios»?", ["De los derrochadores", "De los viajeros", "De los comerciantes", "De los poetas"], "«Los derrochadores son los hermanos de los demonios, y el Demonio es muy ingrato con su Señor» (17:27)."),
"virtues_050": ("¿Cuáles son las «dos palabras ligeras en la lengua, pesadas en la balanza y amadas por el Misericordioso»?", ["«Subhana Allahi wa bi-hamdih, subhana Allahi al-Azim»", "«Allahu akbar, al-hamdu li-Llah»", "«La ilaha illa Allah, Muhammad rasulu Allah»", "«Bismi Allah, ma sha'a Allah»"], "«Dos palabras ligeras en la lengua, pesadas en la balanza, amadas por el Misericordioso: Gloria a Allah y alabanza a Él; gloria a Allah el Inmenso.»"),
}
